begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,created_at,updated_at) select ('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'interchange-'||n||'@example.test',now(),now(),now() from generate_series(1,3)n;
insert into public.workspaces(id,name,created_by) values('e2000000-0000-4000-8000-000000000001','Interchange','e1000000-0000-4000-8000-000000000001');
insert into public.workspace_members(workspace_id,user_id,role) values('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001','owner'),('e2000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000002','member');
insert into public.pages(id,workspace_id,title,owner_id,restricted) values('e3000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','Private export','e1000000-0000-4000-8000-000000000001',true);
select is((select count(*)::int from pg_class where relname in('interchange_jobs','interchange_items') and relrowsecurity),2,'both durable tables enable RLS');
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select set_config('test.job',public.create_interchange_job('e2000000-0000-4000-8000-000000000001','import','e4000000-0000-4000-8000-000000000001',null,null,10,repeat('a',64),'Archive.zip')->>'id',true);
select is(public.create_interchange_job('e2000000-0000-4000-8000-000000000001','import','e4000000-0000-4000-8000-000000000001',null,null,10,repeat('a',64))->>'id',current_setting('test.job'),'lost create ACK returns durable identity');
select throws_ok($$select public.create_interchange_job('e2000000-0000-4000-8000-000000000001','import','e4000000-0000-4000-8000-000000000001',null,null,11,repeat('a',64))$$,'22023',null,'request identity binds source digest and size');
select throws_ok($$select public.confirm_interchange_job(current_setting('test.job')::uuid)$$,'22023',null,'upload cannot skip preview');
select throws_ok($$select public.claim_interchange_job(current_setting('test.job')::uuid,auth.uid(),gen_random_uuid())$$,'42501',null,'client cannot forge server lease');
select throws_ok($$update public.interchange_jobs set confirmed=true$$,'42501',null,'client cannot confirm by direct write');
select throws_ok($$delete from public.interchange_items$$,'42501',null,'client cannot delete receipts');
select is(jsonb_array_length(public.list_interchange_jobs('e2000000-0000-4000-8000-000000000001')->'jobs'),1,'authorized jobs list uses bounded contract');
reset role;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.interchange_jobs),0,'same-workspace member cannot read another actor job');
select throws_ok($$select public.get_interchange_job(current_setting('test.job')::uuid)$$,'42501',null,'job UUID grants no capability');
select throws_ok($$select public.create_interchange_job('e2000000-0000-4000-8000-000000000001','export',gen_random_uuid(),'e3000000-0000-4000-8000-000000000001')$$,'42501',null,'private source cannot be exported by another member');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select public.claim_interchange_job(current_setting('test.job')::uuid,'e1000000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001');
select throws_ok($$select public.claim_interchange_job(current_setting('test.job')::uuid,'e1000000-0000-4000-8000-000000000001',gen_random_uuid())$$,'40001',null,'only one lease can process a job');
select throws_ok($$select public.write_interchange_job(current_setting('test.job')::uuid,'e1000000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001','running','{}','[]')$$,'22023',null,'server cannot import before user confirmation');
select public.put_interchange_item(current_setting('test.job')::uuid,'e1000000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001','entry:0',0,'entry','ready','{"path":"Page.md","format":"markdown","title":"Page"}');
select public.write_interchange_job(current_setting('test.job')::uuid,'e1000000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001','preview','{}','[]');
reset role;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is(public.confirm_interchange_job(current_setting('test.job')::uuid)->>'state','running','user explicitly confirms preview');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select public.claim_interchange_job(current_setting('test.job')::uuid,'e1000000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000002');
reset role;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select set_config('test.page',(public.ensure_interchange_page(current_setting('test.job')::uuid,'e5000000-0000-4000-8000-000000000002','entry:0','Page')->>'pageId'),true);
select is(public.ensure_interchange_page(current_setting('test.job')::uuid,'e5000000-0000-4000-8000-000000000002','entry:0','Changed retry')->>'pageId',current_setting('test.page'),'page creation and receipt share transaction');
select is(public.cancel_interchange_job(current_setting('test.job')::uuid)->>'state','cancelled','cancellation is durable');
select throws_ok($$select public.ensure_interchange_page(current_setting('test.job')::uuid,'e5000000-0000-4000-8000-000000000002','entry:0','Page')$$,'40001',null,'cancelled lease cannot continue writes');
reset role;
set local role anon;
select throws_ok($$select public.list_interchange_jobs('e2000000-0000-4000-8000-000000000001')$$,'42501',null,'anonymous jobs access is denied');
select throws_ok($$insert into public.interchange_items(job_id,workspace_id,actor_id,key,index,kind) values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),'x',0,'entry')$$,'42501',null,'anonymous cannot inject receipts');
reset role;
select * from finish();
rollback;
